// Automatically merge extensions across all languages in window.TRANSLATIONS
if (typeof window !== "undefined" && window.TRANSLATIONS) {
  Object.keys(window.TRANSLATIONS).forEach(function(langKey) {
    var ext = SYSTEM_EXTENSIONS[langKey] || SYSTEM_EXTENSIONS["en"] || SYSTEM_EXTENSIONS["es"];
    window.TRANSLATIONS[langKey].location = Object.assign({}, ext.location);
    window.TRANSLATIONS[langKey].tracking = Object.assign({}, ext.tracking);
    window.TRANSLATIONS[langKey].owner = Object.assign({}, ext.owner);
  });
}

window.t = function(keyPath, fallback) {
    if (!keyPath) return fallback || '';
    var lang = window.currentLang || (typeof localStorage !== 'undefined' && localStorage.getItem('alkarram_language')) || 'es';
    function resolve(obj, path) {
        if (!obj || !path) return undefined;
        var parts = path.split('.');
        var curr = obj;
        for (var i = 0; i < parts.length; i++) {
            if (curr == null) return undefined;
            curr = curr[parts[i]];
        }
        return curr;
    }

    if (keyPath === 'topBar.delivery') {
        var status = (typeof window.checkRestaurantOpenStatus === 'function') 
            ? window.checkRestaurantOpenStatus() 
            : ((typeof checkRestaurantOpenStatus === 'function') ? checkRestaurantOpenStatus() : null);
        var isWeekend = status ? (status.dayName === 'Fri' || status.dayName === 'Sat' || status.dayName === 'Sun') : false;
        var subKey = isWeekend ? 'topBar.deliveryWeekend' : 'topBar.deliveryWeekday';
        var dynRes = resolve(window.TRANSLATIONS[lang], subKey) || resolve(window.TRANSLATIONS['es'], subKey);
        if (dynRes !== undefined) return dynRes;
    }

    var res = resolve(window.TRANSLATIONS[lang], keyPath);
    if (res !== undefined) return res;
    var esRes = resolve(window.TRANSLATIONS['es'], keyPath);
    if (esRes !== undefined) return esRes;
    return fallback !== undefined ? fallback : keyPath;
};

window.tProduct = function(productId) {
    var lang = window.currentLang || (typeof localStorage !== 'undefined' && localStorage.getItem('alkarram_language')) || 'es';
    if (window.TRANSLATIONS[lang] && window.TRANSLATIONS[lang].products && window.TRANSLATIONS[lang].products[productId]) {
        return window.TRANSLATIONS[lang].products[productId];
    }
    if (window.TRANSLATIONS['es'] && window.TRANSLATIONS['es'].products && window.TRANSLATIONS['es'].products[productId]) {
        return window.TRANSLATIONS['es'].products[productId];
    }
    return null;
};

window.tOption = function(optionText) {
    if (!optionText) return '';
    var lang = window.currentLang || (typeof localStorage !== 'undefined' && localStorage.getItem('alkarram_language')) || 'es';
    if (window.TRANSLATIONS[lang] && window.TRANSLATIONS[lang].options && window.TRANSLATIONS[lang].options[optionText]) {
        return window.TRANSLATIONS[lang].options[optionText];
    }
    if (window.TRANSLATIONS['es'] && window.TRANSLATIONS['es'].options && window.TRANSLATIONS['es'].options[optionText]) {
        return window.TRANSLATIONS['es'].options[optionText];
    }
    return optionText;
};

window.tCategory = function(catKey) {
    if (!catKey) return '';
    var lower = catKey.toLowerCase();
    return window.t('categories.' + lower, catKey);
};

window.tBadge = function(badgeText) {
    if (!badgeText) return '';
    var lower = badgeText.toLowerCase();
    if (lower === 'popular') return window.t('badges.popular', 'Popular');
    if (lower === 'recomendado' || lower === 'recommended') return window.t('badges.recommended', 'Recomendado');
    if (lower === 'el más pedido' || lower === 'bestseller') return window.t('badges.bestseller', 'El Más Pedido');
    return badgeText;
};
